import {emptyWallet} from './session.js';
import {saveRecurringRule,ensureRecurringThroughMonth,recurringChargesForMonth,setRecurringPayment,settleRecurringMonth} from './recurring.js';
import {saveCard,invoiceDue,cardTextColor,DEFAULT_CARD_COLOR} from './cards.js';
import {canResetTransactions,resetTransactions} from './reset.js';
import {saveInstallmentPurchase,splitInstallments,installmentLabel} from './installments.js';
import {monthlyCashflow} from './cashflow.js';
import {saveEmployment,salaryDraft} from './employment.js';
import {methods,credit,monthOf,addMonth,invoiceMonth,dueDate,saveTransaction,removeTransaction,settleInvoice,balance,metrics,addCategory,addCard,validateState} from './model.js';
const $=s=>document.querySelector(s),money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v/100),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const desktop = window.castorDesktop;
let month=today().slice(0,7),page='overview',state=emptyWallet(),confirmAction,toastTimer;
let storageUnavailable = false;
if (desktop) {
  try {
    const result = desktop.loadWallet();
    if (!result.ok) throw Error();
    if (result.value) state = validateState(result.value);
  } catch {
    storageUnavailable = true;
  }
  document.querySelector('.profile small').textContent = 'Dados neste computador';
  document.querySelector('#storage-notice').textContent = storageUnavailable
    ? 'Não foi possível abrir a carteira local. As alterações estão bloqueadas para preservar o arquivo.'
    : 'Sua carteira é salva neste computador automaticamente. Exporte um JSON para manter uma cópia ou usar em outro computador.';
}
function saveState(next) {
  if (storageUnavailable || (desktop && !desktop.saveWallet(next)?.ok)) {
    throw Error('Não foi possível gravar a carteira neste computador.');
  }
  state = next;
}
function commit(next) {
  try {
    saveState(ensureRecurringThroughMonth(next,month).state);
    render();
    return true;
  } catch(error) {
    toast('Não foi possível atualizar a carteira: '+error.message);
    return false;
  }
}
function syncRecurring() {
  try {
    const next = ensureRecurringThroughMonth(state,month).state;
    if (next !== state) saveState(next);
  } catch(error) {
    toast('Não foi possível atualizar as recorrências: '+error.message);
  }
}
const expensesHelp = `
  <p>Este valor considera todas as despesas do mês selecionado (<strong>pagas e pendentes</strong>), seguindo duas regras:</p>
  <ul>
    <li><strong>PIX, débito e dinheiro:</strong> entram pela data em que o gasto foi feito.</li>
    <li><strong>Cartão de crédito (à vista ou parcelado):</strong> entram pelo mês da fatura.</li>
  </ul>`;
const pendingHelp = `
  <p>Soma apenas as despesas <strong>ainda pendentes</strong> até o período selecionado, incluindo o que ficou em aberto de meses anteriores:</p>
  <ul>
    <li><strong>À vista (PIX, débito, dinheiro):</strong> considera a data do lançamento.</li>
    <li><strong>Cartão de crédito:</strong> considera o mês da fatura, mesmo que ela vença no mês seguinte.</li>
    <li><strong>Compromissos futuros:</strong> não entram neste cálculo.</li>
  </ul>`;
function statHelp(id, label, explanation) {
  return `<div class="stat-help"><span class="stat-help-icon" tabindex="0" aria-label="Sobre: ${label}" aria-describedby="${id}">?</span><div class="stat-tooltip" role="tooltip" id="${id}">${explanation}</div></div>`;
}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
const category=id=>state.categories.find(c=>c.id===id),card=id=>state.cards.find(c=>c.id===id),fmtDate=s=>s?s.split('-').reverse().join('/'):'—';
const monthLabel=m=>new Date(m+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
function rowsTable(rows,actions=false){return `<div class="table-wrap"><table><thead><tr><th>DESCRIÇÃO</th><th>CATEGORIA</th><th>DATA</th><th>PAGAMENTO</th><th>STATUS</th><th>VALOR</th>${actions?'<th>AÇÕES</th>':''}</tr></thead><tbody>${rows.length?rows.map(t=>`<tr><td><div class="description-cell"><span class="category-icon">${t.type==='income'?'↙':'↗'}</span><strong>${esc(t.description)}${installmentLabel(t)}${t.recurringId?'<small class="recurring-badge">↻ Mensal</small>':''}</strong></div></td><td><span class="category-pill">${esc(category(t.category)?.name)}</span></td><td>${fmtDate(t.date)}</td><td>${credit(t)?esc(card(t.card)?.name)+'<br><small>Fatura '+esc(t.invoice)+'</small>':esc(t.method)}</td><td><span class="pill ${t.status}">● ${t.status==='paid'?'Pago':'Pendente'}</span></td><td class="value ${t.type==='income'?'income':'expense'}">${t.type==='income'?'+':'−'} ${money(t.amount)}</td>${actions?`<td><div class="row-actions"><button data-edit="${esc(t.id)}" aria-label="Editar ${esc(t.description)}">Editar</button><button data-delete="${esc(t.id)}" class="delete" aria-label="Excluir ${esc(t.description)}">Excluir</button></div></td>`:''}</tr>`).join(''):`<tr><td colspan="${actions?7:6}" class="empty">Nenhuma transação por aqui. Adicione seu primeiro lançamento.</td></tr>`}</tbody></table></div>`;}
function lineChart(){const months=Array.from({length:6},(_,i)=>addMonth(month,i-5)),values=months.map(m=>balance(state,m+'-31'));const min=Math.min(0,...values),max=Math.max(10000,...values),span=max-min;const x=i=>54+i*88,y=v=>155-(v-min)/span*130;const points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');return `<svg class="line-chart" viewBox="0 0 525 200" role="img" aria-label="Saldo acumulado ao final de cada mês: ${months.map((m,i)=>monthLabel(m)+': '+money(values[i])).join('; ')}"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#76aa8b" stop-opacity=".19"/><stop offset="1" stop-color="#76aa8b" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{const v=min+span*i/3;return `<line x1="54" x2="500" y1="${y(v)}" y2="${y(v)}" stroke="#edf0e9" stroke-dasharray="3 4"/><text x="0" y="${y(v)+3}" class="chart-label">${(v/100000).toLocaleString('pt-BR',{maximumFractionDigits:1})} mil</text>`;}).join('')}<polygon points="54,155 ${points} 494,155" fill="url(#fill)"/><polyline points="${points}" fill="none" stroke="#5b8f74" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3.8" fill="#fff" stroke="#5b8f74" stroke-width="2"><title>${monthLabel(months[i])}: ${money(v)}</title></circle><text x="${x(i)}" y="185" text-anchor="middle" class="chart-label">${new Date(months[i]+'-15').toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</text>`).join('')}</svg>`;}
function carryoverPanel(c){return `<article class="panel carryover-panel"><div class="panel-heading"><h2>De um mês para o outro</h2><span class="pill ${c.carried<0?'deficit':'paid'}">${c.carried<0?'Déficit acumulado':c.carried>0?'Saldo trazido':'Saldo anterior zerado'}</span></div><p class="panel-subtitle">O saldo final de ${esc(monthLabel(addMonth(month,-1)))} é o ponto de partida de ${esc(monthLabel(month))}.</p><div class="cashflow-equation"><div><span>Saldo anterior</span><strong class="${c.carried<0?'negative':''}">${money(c.carried)}</strong><small>Inclui o saldo inicial e o histórico pago</small></div><div><span>＋ Entradas realizadas</span><strong>${money(c.received)}</strong><small>Receitas recebidas neste mês</small></div><div><span>− Saídas realizadas</span><strong>${money(c.paid)}</strong><small>Inclui faturas pagas neste mês</small></div><div><span>＝ Saldo realizado</span><strong class="${c.closing<0?'negative':''}">${money(c.closing)}</strong><small>Transportado para o mês seguinte</small></div></div><p class="month-result">Resultado realizado só deste mês: <b class="${c.result<0?'negative':''}">${money(c.result)}</b> · ${c.result<0?'As saídas superaram as entradas.':c.result>0?'As entradas superaram as saídas.':'Entradas e saídas se equilibraram.'}</p><div class="cashflow-forecast"><div><span>Saldo previsto após pendências</span><strong class="${c.projected<0?'negative':''}">${money(c.projected)}</strong></div><p>Saldo realizado + ${money(c.pendingIncome)} a receber − ${money(c.pendingExpenses)} a pagar até este mês.${c.overdueExpenses?' Desse valor a pagar, '+money(c.overdueExpenses)+' vem de meses anteriores.':''} Faturas entram pelo vencimento; compromissos futuros ficam no mês correspondente.</p></div><p class="mini-insight">A previsão usa apenas transações cadastradas. O salário em Emprego entra nos cálculos depois de ser salvo como receita em Nova transação.</p></article>`;}
function overview(){const c=monthlyCashflow(state,month);const m=metrics(state,month),cats=state.categories.map(c=>({...c,total:m.rows.filter(t=>t.type==='expense'&&t.category===c.id).reduce((a,t)=>a+t.amount,0)})).filter(c=>c.total).sort((a,b)=>b.total-a.total);const share=m.expenses?m.credit/m.expenses:0;const end=month+'-31';const pendingCards=m.rows.filter(t=>credit(t)&&t.status==='pending').reduce((a,t)=>a+t.amount,0);const recent=[...m.rows].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `<div class="stats"><article class="stat"><div class="stat-title">Saldo realizado <span class="stat-icon">◈</span></div><div class="amount">${money(balance(state,end))}</div><small>Acumulado até o fim do mês</small></article><article class="stat"><div class="stat-title">Receitas do mês <span class="stat-icon income">↙</span></div><div class="amount">${money(m.income)}</div><small>Recebidas e a receber</small></article><article class="stat"><div class="stat-title">Despesas do mês <span class="stat-icon expense">↗</span></div><div class="amount">${money(m.expenses)}</div><small>Por competência · inclui faturas</small>${statHelp("help-expenses","Despesas do mês",expensesHelp)}</article><article class="stat"><div class="stat-title">A pagar até este mês <span class="stat-icon pending">◷</span></div><div class="amount">${money(c.pendingExpensesByMonth)}</div><small>Inclui pendências anteriores</small>${statHelp("help-pending","A pagar até este mês",pendingHelp)}</article></div>${carryoverPanel(c)}<div class="chart-grid"><article class="panel panel-inner"><div class="panel-heading"><h2>Evolução do saldo</h2><div class="legend"><span class="dot"></span> Saldo realizado</div></div><p class="panel-subtitle">Seu caminho nos últimos seis meses</p>${lineChart()}</article><article class="panel panel-inner"><div class="panel-heading"><h2>Gastos por categoria</h2><small>${cats.length} categorias</small></div><p class="panel-subtitle">Onde seu dinheiro está sendo usado</p><div class="category-bars">${cats.length?cats.map(c=>`<div class="bar-row"><div><span class="bar-name"><i class="dot" style="background:${c.color}"></i>${esc(c.name)}</span><span>${money(c.total)}</span></div><div class="bar-track"><div class="bar-fill" style="width:${c.total/cats[0].total*100}%;background:${c.color}"></div></div></div>`).join(''):'<p class="empty">Sem despesas neste mês.</p>'}</div></article></div><div class="chart-grid"><article class="panel panel-inner"><div class="panel-heading"><h2>Como você paga</h2><small>DESPESAS DO MÊS</small></div><div class="comparison"><svg class="donut" viewBox="0 0 140 140" role="img" aria-label="Cartão: ${money(m.credit)}. À vista: ${money(m.cash)}."><circle cx="70" cy="70" r="51" fill="none" stroke="#edf0e9" stroke-width="14"/><circle cx="70" cy="70" r="51" fill="none" stroke="#a8bda4" stroke-width="14" stroke-dasharray="${m.expenses?320.44:0} 320.44" transform="rotate(-90 70 70)"/><circle cx="70" cy="70" r="51" fill="none" stroke="#3f6b53" stroke-width="14" stroke-dasharray="${share*320.44} 320.44" transform="rotate(-90 70 70)"/><text x="70" y="65" text-anchor="middle" class="chart-label">Total</text><text x="70" y="83" text-anchor="middle" font-size="12" fill="#405843" font-weight="600">${money(m.expenses)}</text></svg><div class="comparison-details"><div class="compare-item"><i class="dot" style="background:#3f6b53"></i><div>Cartão de crédito<strong>${money(m.credit)}</strong></div><span>${Math.round(share*100)}%</span></div><div class="compare-item"><i class="dot" style="background:#a8bda4"></i><div>À vista · PIX, débito e dinheiro<strong>${money(m.cash)}</strong></div><span>${m.expenses?100-Math.round(share*100):0}%</span></div></div></div><p class="mini-insight">Compras no cartão entram pelo mês da fatura; pagamentos à vista, pela data da transação.</p></article><article class="panel panel-inner"><div class="panel-heading"><h2>De olho nas faturas</h2><span class="card-chip">▤</span></div><div class="invoice-preview"><div><p class="panel-subtitle">Total pendente · ${esc(monthLabel(month))}</p><div class="invoice-value">${money(pendingCards)}</div><span class="pill ${pendingCards?'pending':'paid'}">● ${pendingCards?'Aguardando pagamento':'Tudo em dia'}</span></div></div><p class="mini-insight">Pague a fatura para atualizar o saldo realizado, sem duplicar suas despesas.</p><button class="text-button" data-page="cards">Ver cartões e faturas →</button></article></div><article class="panel"><div class="table-heading"><h2>Últimas transações <small class="muted">· ${esc(monthLabel(month))}</small></h2><button class="text-button" data-page="transactions">Ver todas →</button></div>${rowsTable(recent)}</article>`;}
function transactions(){return `<article class="panel"><div class="table-heading"><h2>Seus lançamentos</h2><div class="transaction-tools"><button data-page="recurring" class="secondary">↻ Despesas recorrentes</button><span id="result-count" class="muted"></span></div></div><div class="filter-row"><input id="search" placeholder="Buscar por descrição..." aria-label="Buscar transações"><select id="type-filter" aria-label="Filtrar por tipo"><option value="">Todos os tipos</option><option value="income">Receitas</option><option value="expense">Despesas</option></select><select id="status-filter" aria-label="Filtrar por status"><option value="">Todos os status</option><option value="paid">Pagos</option><option value="pending">Pendentes</option></select><select id="category-filter" aria-label="Filtrar categoria"><option value="">Todas as categorias</option>${state.categories.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div><div id="transactions-table"></div></article><p class="notice">O período considera o mês da fatura para compras no cartão e a data do lançamento para os demais meios. Edite um lançamento para alterar valor, categoria, status ou fatura.</p>`;}
function filterTransactions(){const query=$('#search').value.toLocaleLowerCase('pt-BR'),type=$('#type-filter').value,status=$('#status-filter').value,cat=$('#category-filter').value;const rows=metrics(state,month).rows.filter(t=>t.description.toLocaleLowerCase('pt-BR').includes(query)&&(!type||t.type===type)&&(!status||t.status===status)&&(!cat||t.category===cat)).sort((a,b)=>b.date.localeCompare(a.date));$('#transactions-table').innerHTML=rowsTable(rows,true);$('#result-count').textContent=rows.length+' transações';}
function cardsPage(){return `<div class="table-heading" style="padding:0 0 20px"><h2>Seus cartões</h2><button id="add-card" class="secondary">＋ Adicionar cartão</button></div><div class="card-grid">${state.cards.map(c=>{const tx=state.transactions.filter(t=>credit(t)&&t.card===c.id&&t.invoice===month),total=tx.reduce((a,t)=>a+t.amount,0),pending=tx.filter(t=>t.status==='pending').reduce((a,t)=>a+t.amount,0);return `<article class="panel panel-inner"><div class="bank-card" style="background:${c.color||DEFAULT_CARD_COLOR};color:${cardTextColor(c.color)}"><div class="card-title"><strong>${esc(c.name)}</strong><button class="card-edit-button" data-edit-card="${esc(c.id)}" aria-label="Editar cartão ${esc(c.name)}">Editar cartão</button></div><small>castor wallet <span style="float:right">CRÉDITO</span></small></div><div class="panel-heading"><h2>Fatura de ${esc(monthLabel(month))}</h2><span class="pill ${pending?'pending':'paid'}">${pending?'Pendente':'Em dia'}</span></div><p class="panel-subtitle">Fecha dia ${tx.find(t=>t.invoiceClosingDay)?.invoiceClosingDay??c.closing} · Vence em ${fmtDate(invoiceDue(state,c.id,month))}</p><div class="invoice-value">${money(total)}</div><p class="muted">Pago: ${money(total-pending)} · Pendente: ${money(pending)}</p><div class="guide-actions"><button class="primary" data-settle="${esc(c.id)}" ${pending?'':'disabled'}>Pagar fatura · ${money(pending)}</button></div><div style="margin-top:20px">${tx.length?tx.map(t=>`<div class="bar-row" style="padding:10px 0;border-bottom:1px solid #f0f2ed"><div><span>${esc(t.description)}${installmentLabel(t)} <small class="muted">${t.status==='paid'?'· Pago':''}</small></span><strong>${money(t.amount)}</strong></div></div>`).join(''):'<p class="empty">Nenhuma compra nesta fatura.</p>'}</div></article>`;}).join('')}</div><p class="notice">Use Editar cartão para alterar nome, cor, fechamento e vencimento. As faturas já cadastradas mantêm suas datas. Para parcelar uma compra, use Nova transação → Cartão de crédito e preencha o valor total e a quantidade de parcelas. O mês da fatura corresponde ao fechamento. Se o vencimento ocorre antes ou no mesmo dia do fechamento, ele cai no mês seguinte. Ao pagar, somente as compras pendentes desta fatura são quitadas. Para estornar ou corrigir, edite a compra em Transações.</p>`;}
function categoriesPage(){return `<div class="table-heading" style="padding:0"><h2>Uma categoria para cada escolha</h2><button id="add-category" class="secondary">＋ Nova categoria</button></div><p class="notice">Crie uma categoria e ela aparecerá imediatamente nos lançamentos, filtros e gráficos. Os cálculos usam identificadores estáveis; você não precisa ajustar nenhuma fórmula.</p><div class="category-grid">${state.categories.map(c=>`<div class="category-tile"><span class="dot" style="background:${c.color};width:12px;height:12px"></span><div>${esc(c.name)}<small>${state.transactions.filter(t=>t.category===c.id).length} lançamentos</small></div></div>`).join('')}</div>`;}
function guide(){return `<div class="guide-grid"><article class="panel"><h2>01 · Comece pela sua rotina</h2><ol><li>Use <b>Nova transação</b> para registrar receitas e despesas.</li><li>Preencha data, descrição, valor, categoria e meio de pagamento.</li><li>Marque <b>Pago</b> apenas quando o dinheiro tiver sido recebido ou pago.</li><li>Em <b>Transações</b>, busque, edite ou exclua um lançamento.</li></ol><p>${desktop?'A carteira retoma os dados salvos neste computador. Importe um JSON se quiser trazer um backup existente.':'A carteira sempre abre zerada. Importe seu backup JSON para continuar de onde parou.'}</p><div class="guide-actions"><button id="clear-data" class="secondary danger-outline">Apagar todas as transações</button></div></article><article class="panel"><h2>02 · Categorias sem complicação</h2><ol><li>Abra <b>Categorias → Nova categoria</b>.</li><li>Escolha um nome e uma cor.</li><li>Selecione a categoria ao adicionar ou editar um lançamento.</li></ol><p>Ela passa a compor os gráficos automaticamente. Categorias não são apagadas para preservar o histórico. Cadastre novos meios de crédito em <b>Cartões e faturas</b>.</p></article><article class="panel"><h2>03 · Entenda os números</h2><p><b>Saldo realizado:</b> saldo inicial + receitas pagas − despesas pagas, acumulados até o fim do mês. Para cartão, usa a data de pagamento.<br><b>Saldo anterior:</b> sobra ou déficit acumulado até o fim do mês passado. Ele soma às entradas e é reduzido pelas saídas realizadas deste mês, sem criar outra transação.<br><b>Saldo previsto:</b> saldo realizado + receitas pendentes − despesas pendentes até o fim do mês, incluindo atrasados; cartão usa o vencimento da fatura. Compromissos futuros entram no mês correspondente.<br><b>Receitas e despesas:</b> incluem pagos e pendentes por competência no mês selecionado.<br><b>Cartões:</b> compras após o fechamento entram na próxima fatura. O mês sugerido pode ser ajustado.<br><b>Pagamento da fatura:</b> quita compras pendentes, sem lançar uma segunda despesa.</p></article><article class="panel"><h2>04 · Seus dados, sob seu controle</h2><p>${desktop?'Os dados são salvos automaticamente neste computador. Use a exportação para guardar uma cópia ou transferir seus dados para outro computador.':'Os dados ficam apenas na memória desta página. Atualizar, fechar ou abrir outra aba inicia uma carteira zerada. Importe seu JSON ao iniciar e exporte um backup atualizado antes de sair.'}</p><p>Em <b>Transações → Despesas recorrentes</b>, cadastre contas mensais. As despesas são incluídas automaticamente até o mês selecionado, sem duplicar. Assinale Pago nas cobranças para registrar o pagamento. Em <b>Cartões e faturas → Editar cartão</b>, ajuste nome, cor e datas.</p><div class="guide-actions"><button id="export-guide" class="secondary">Exportar backup</button><button id="import-button" class="secondary">Importar backup</button></div><label style="display:block;font-size:11px;color:#7d897f;margin-top:20px">Saldo inicial da carteira (R$)<input id="opening" type="number" step="0.01" value="${state.opening/100}" style="display:block;padding:10px;border:1px solid #dce5d9;border-radius:6px;margin-top:8px;width:100%"></label><button id="save-opening" class="text-button">Salvar saldo inicial →</button></article></div>`;}
function employmentPage(){
const job=state.employment;
const salaryCategory=job?.category||state.categories.find(c=>c.name.toLocaleLowerCase('pt-BR')==='salário')?.id;
return `<div class="guide-grid employment-layout"><article class="panel"><h2>Meu emprego</h2><p class="notice">Cadastre o valor que você recebe por mês. Use o salário líquido para acompanhar o dinheiro que entra na sua carteira.</p><form id="employment-form"><label>Empresa (opcional)<input name="employer" maxlength="80" placeholder="Ex.: Minha empresa" value="${esc(job?.employer||'')}"></label><div class="form-grid"><label>Salário mensal (R$)<input name="amount" required type="number" min="0.01" max="999999999" step="0.01" placeholder="0,00" value="${job?job.amount/100:''}"></label><label>Dia de recebimento<input name="payday" required type="number" min="1" max="31" value="${job?.payday||5}"></label><label>Categoria<select name="category" required>${state.categories.map(c=>`<option value="${esc(c.id)}" ${c.id===salaryCategory?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Meio de recebimento<select name="method" required>${methods.filter(m=>m!=='Cartão de crédito').map(m=>`<option ${m===job?.method?'selected':''}>${esc(m)}</option>`).join('')}</select></label></div><p id="employment-error" class="form-error" role="alert"></p><div class="dialog-actions"><button type="submit" class="primary">${job?'Salvar alterações':'Cadastrar salário'}</button></div></form></article><article class="panel"><h2>Seu salário, sem retrabalho</h2>${job?`<p class="panel-subtitle">Salário mensal cadastrado</p><div class="invoice-value">${money(job.amount)}</div><p>${esc(job.employer||'Meu emprego')} · recebimento dia ${job.payday}</p>`:'<p>Cadastre seu salário para preencher suas próximas receitas em poucos cliques.</p>'}<ol><li>Abra <b>Nova transação</b>.</li><li>Escolha <b>Usar salário cadastrado</b>.</li><li>Revise os dados e marque <b>Pago</b> quando receber.</li><li>Salve a transação para incluí-la nos gráficos.</li></ol><p>O lançamento usa o mês selecionado na carteira. Se o dia não existir naquele mês, será usado o último dia do mês. Alterações no cadastro valem para os próximos preenchimentos; receitas anteriores mantêm seus valores.</p><p class="notice">O cadastro não cria receitas automaticamente. Confira os lançamentos do mês antes de adicionar o salário novamente.</p></article></div>`;
}
const pageNames={recurring:['Despesas recorrentes','Suas contas, todos os meses.','Acompanhe as cobranças incluídas automaticamente e assinale os pagamentos do mês.'],employment:['Emprego','Seu trabalho, seus planos.','Cadastre seu salário e simplifique as receitas de cada mês.'],overview:['Visão geral','Seu dinheiro, com clareza.','Acompanhe seu mês e dê espaço aos seus planos.'],transactions:['Transações','Cada movimento, no lugar.','Organize entradas e saídas sem perder nenhum detalhe.'],cards:['Cartões e faturas','Seu cartão, sob controle.','Veja o que já foi pago e prepare-se para os próximos vencimentos.'],categories:['Categorias','Organize do seu jeito.','Uma visão mais clara começa com categorias que fazem sentido para você.'],guide:['Guia rápido','O primeiro passo é simples.','Conheça sua carteira e cuide do que vem pela frente.']};
function render(){syncRecurring();const names=pageNames[page];$('#crumb').textContent=names[0];$('#page-title').textContent=names[1];$('#page-subtitle').textContent=names[2];$('#month').value=month;$('.toolbar').hidden=page==='guide'||page==='categories'||page==='employment';$('#demo-tag').hidden=!state.transactions.some(t=>t.id.startsWith('demo'));$('.local-tag').textContent=desktop?(storageUnavailable?'● Carteira indisponível':'● Dados neste computador'):'● Dados nesta sessão';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page||(page==='recurring'&&b.dataset.page==='transactions')));$('#page-content').innerHTML=({overview,transactions,cards:cardsPage,categories:categoriesPage,employment:employmentPage,recurring:recurringPage,guide})[page]();if(page==='transactions'){filterTransactions();for(const id of ['search','type-filter','status-filter','category-filter'])$('#'+id).addEventListener('input',filterTransactions);}}
function navigate(p){page=pageNames[p]?p:'overview';location.hash=page;render();}
function showConfirm(title,text,action,date=false){$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;$('#confirm-date-field').hidden=!date;$('#confirm-date').value=today();$('#confirm-date').required=date;$('#confirm-error').textContent='';confirmAction=action;$('#confirm-dialog').showModal();}
const form=$('#transaction-form');
function updateInstallmentPreview(){
const isCredit=form.elements.method.value==='Cartão de crédito';
const existing=state.transactions.find(t=>t.id===form.elements.id.value);
$('#invoice-label').textContent=existing?'Mês da fatura':'Mês da primeira fatura';$('#installments-field').hidden=!isCredit||!!existing;
form.elements.installments.required=isCredit&&!existing;
form.elements.installments.disabled=!isCredit||!!existing;
$('#installments-preview').hidden=!isCredit;
$('#amount-label').textContent=isCredit&&!existing?'Valor total da compra (R$)':'Valor (R$)';
if(!isCredit)return;
if(existing){$('#installments-preview').textContent=existing.installment?'Editando a parcela '+existing.installment.index+'/'+existing.installment.count+'. As alterações e a exclusão afetam somente esta parcela.':'Este lançamento já existe. Para uma nova compra parcelada, use Nova transação.';return;}
try{const amounts=splitInstallments(Math.round(Number(form.elements.amount.value)*100),Number(form.elements.installments.value));const count=amounts.length;const min=Math.min(...amounts),max=Math.max(...amounts);$('#installments-preview').textContent=count===1?'Compra em uma única fatura.':count+' parcelas de '+(min===max?money(min):money(min)+' a '+money(max))+'. Total: '+money(amounts.reduce((a,b)=>a+b,0))+'. A primeira parcela entra na fatura selecionada e as demais, nos meses seguintes. Se marcar Pago, somente a primeira parcela será quitada.';}catch(error){$('#installments-preview').textContent=error.message;}
}
function updateCardFields(suggest=false){const isCredit=form.elements.method.value==='Cartão de crédito';$('#card-field').hidden=!isCredit;$('#invoice-field').hidden=!isCredit;const needsPaidDate=form.elements.status.value==='paid'&&(isCredit||state.transactions.some(t=>t.id===form.elements.id.value&&t.recurringId));$('#paid-date-field').hidden=!needsPaidDate;form.elements.card.required=isCredit;form.elements.invoice.required=isCredit;form.elements.paidDate.required=needsPaidDate;if(isCredit&&suggest){const c=card(form.elements.card.value);if(c&&form.elements.date.value)form.elements.invoice.value=invoiceMonth(form.elements.date.value,c.closing);}updateInstallmentPreview();}
function openTransaction(id){form.reset();$('#salary-shortcut').hidden=!!id;$('#use-salary').textContent=state.employment?'Usar salário cadastrado':'Cadastrar em Emprego';$('#salary-shortcut-description').textContent=state.employment?money(state.employment.amount)+' por mês · preenche uma receita pendente.':'Cadastre seu salário para preencher esta receita.';$('#transaction-error').textContent='';form.elements.category.innerHTML=state.categories.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');form.elements.method.innerHTML=methods.map(m=>`<option>${esc(m)}</option>`).join('');form.elements.card.innerHTML=state.cards.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');form.elements.id.value=id||crypto.randomUUID();form.elements.date.value=today();form.elements.paidDate.value=today();const t=state.transactions.find(x=>x.id===id);if(t)for(const [key,value] of Object.entries(t))if(form.elements[key])form.elements[key].value=key==='amount'?value/100:value;$('#form-title').textContent=t?'Editar transação':'Nova transação';updateCardFields(!t);$('#transaction-dialog').showModal();}
form.addEventListener('submit',e=>{e.preventDefault();try{const existing=state.transactions.find(x=>x.id===form.elements.id.value);const t={...existing,...Object.fromEntries(new FormData(form))};const count=credit(t)&&!existing?Number(t.installments):1;delete t.installments;t.amount=Math.round(Number(t.amount)*100);t.description=t.description.trim();if(!credit(t)){delete t.card;delete t.invoice;if(!t.recurringId||t.status!=='paid')delete t.paidDate;}else if(t.status==='pending')delete t.paidDate;if(commit(saveInstallmentPurchase(state,t,count))){$('#transaction-dialog').close();toast('Transação salva.');}}catch(error){$('#transaction-error').textContent=error.message;}});
for(const name of ['amount','installments'])form.elements[name].addEventListener('input',updateInstallmentPreview);
for(const name of ['method','status','date','card'])form.elements[name].addEventListener('change',()=>updateCardFields(name!=='status'));
$('#confirm-form').addEventListener('submit',e=>{e.preventDefault();try{const done=confirmAction($('#confirm-date').value);if(done!==false)$('#confirm-dialog').close();}catch(error){$('#confirm-error').textContent=error.message;}});
$('#category-form').addEventListener('submit',e=>{e.preventDefault();try{const data=new FormData(e.target);if(commit(addCategory(state,data.get('name'),data.get('color')))){$('#category-dialog').close();toast('Categoria criada.');}}catch(error){$('#category-error').textContent=error.message;}});
$('#card-form').addEventListener('submit',e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));if(commit(saveCard(state,{id:d.id||undefined,name:d.name,closing:Number(d.closing),due:Number(d.due),color:d.color}))){$('#card-dialog').close();toast(d.id?'Cartão atualizado.':'Cartão adicionado.');}}catch(error){$('#card-error').textContent=error.message;}});
function openResetDialog(){
$('#reset-form').reset();$('#reset-error').textContent='';$('#reset-submit').disabled=true;
const total=state.transactions.length,parcels=state.transactions.filter(t=>t.installment).length;
$('#reset-summary').textContent=total+' lançamento(s) de todos os meses serão apagados, incluindo '+parcels+' parcela(s). O saldo inicial será zerado. Categorias, cartões, Emprego e cadastros de recorrências serão mantidos. As cobranças apagadas não serão recriadas; novos meses seguem as recorrências ativas. ' + (desktop ? 'A limpeza será salva neste computador.' : 'A limpeza vale para esta sessão.');
$('#reset-dialog').showModal();
}
$('#reset-confirmation').addEventListener('input',()=>{$('#reset-submit').disabled=!canResetTransactions($('#reset-confirmation').value);$('#reset-error').textContent='';});
$('#reset-form').addEventListener('submit',e=>{e.preventDefault();try{if(commit(resetTransactions(state,$('#reset-confirmation').value))){$('#reset-dialog').close();toast('Todas as transações foram apagadas e o saldo foi zerado.');}}catch(error){$('#reset-error').textContent=error.message;}});
async function exportBackup(){
  const filename = 'castor-wallet-' + today() + '.json';
  const content = JSON.stringify(state, null, 2);
  if (window.castorDesktop) {
    try {
      if (await window.castorDesktop.saveBackup(filename, content)) toast('Backup exportado.');
    } catch {
      toast('Não foi possível salvar o backup. Escolha outra pasta e tente novamente.');
    }
    return;
  }
  const blob = new Blob([content], {type:'application/json'});
  const url = URL.createObjectURL(blob), link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  toast('Backup exportado.');
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){navigate(b.dataset.page);return;}if(b.hasAttribute('data-close')){b.closest('dialog').close();return;}if(b.dataset.editCard)openCard(b.dataset.editCard);if(b.dataset.editRule)openRecurring(b.dataset.editRule);if(b.dataset.newRule)openRecurring(null,b.dataset.newRule);if(b.dataset.toggleRule){const rule=state.recurringRules.find(r=>r.id===b.dataset.toggleRule);if(rule)commit(saveRecurringRule(state,{...rule,active:!rule.active},month));}if(b.dataset.edit)openTransaction(b.dataset.edit);if(b.dataset.delete){const t=state.transactions.find(t=>t.id===b.dataset.delete);showConfirm('Excluir transação?',`“${t.description}${installmentLabel(t)}” será removida dos saldos e gráficos.${t.installment?" Somente esta parcela será excluída; as demais continuam nas respectivas faturas.":""}`,()=>commit(removeTransaction(state,t.id)));}if(b.dataset.settle){const c=card(b.dataset.settle);showConfirm('Pagar fatura?',`As compras pendentes de ${c.name} na fatura de ${monthLabel(month)} serão marcadas como pagas.`,date=>commit(settleInvoice(state,c.id,month,date)),true);}switch(b.id){case 'use-salary':if(!state.employment){$('#transaction-dialog').close();navigate('employment');break;}try{const draft=salaryDraft(state,month);for(const [key,value] of Object.entries(draft))if(form.elements[key])form.elements[key].value=key==='amount'?value/100:value;updateCardFields();$('#transaction-error').textContent='';toast('Salário preenchido. Revise os dados antes de salvar.');}catch(error){$('#transaction-error').textContent=error.message;}break;case 'manage-recurring':$('#transaction-dialog').close();navigate('recurring');break;case 'add-recurring':openRecurring();break;case 'pay-recurring-month':{const pending=recurringChargesForMonth(state,month).filter(t=>t.status==='pending');if(pending.length)showConfirm('Marcar recorrências do mês como pagas?',pending.length+' cobrança(s) de '+monthLabel(month)+' serão quitadas na data informada. Não será criada uma segunda despesa.',date=>commit(settleRecurringMonth(state,month,date)),true);break;}case 'new-transaction':openTransaction();break;case 'reset-export':case 'backup':case 'export-guide':exportBackup();break;case 'prev-month':month=addMonth(month,-1);render();break;case 'next-month':month=addMonth(month);render();break;case 'add-category':$('#category-form').reset();$('#category-error').textContent='';$('#category-dialog').showModal();break;case 'add-card':openCard();break;case 'clear-data':openResetDialog();break;case 'import-header':case 'import-button':$('#import-file').click();break;case 'save-opening':{const value=$('#opening').value;const cents=Math.round(Number(value)*100);if(!value.trim()||!Number.isSafeInteger(cents))toast('Informe um saldo inicial válido.');else if(commit({...state,opening:cents}))toast('Saldo inicial atualizado.');break;}}});
document.addEventListener('submit',e=>{if(e.target.id!=='employment-form')return;e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));if(commit(saveEmployment(state,{employer:d.employer,amount:Math.round(Number(d.amount)*100),payday:Number(d.payday),category:d.category,method:d.method})))toast('Salário cadastrado atualizado.');}catch(error){$('#employment-error').textContent=error.message;}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Use um backup de até 5 MB.');const imported=validateState(JSON.parse(await file.text()));showConfirm('Importar backup?',`${imported.transactions.length} transações substituirão os dados atuais. Exporte seus dados antes para preservá-los.`,()=>commit(imported));}catch(error){toast('Backup não importado: '+error.message);}e.target.value='';});
$('#month').addEventListener('change',e=>{if(/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){month=e.target.value;render();}});window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pageNames[p]&&p!==page){page=p;render();}});page=pageNames[location.hash.slice(1)]?location.hash.slice(1):'overview';render();

function openCard(id){
const f=$('#card-form');f.reset();$('#card-error').textContent='';
const c=state.cards.find(c=>c.id===id);f.elements.id.value=c?.id||'';
f.elements.name.value=c?.name||'';f.elements.closing.value=c?.closing||25;f.elements.due.value=c?.due||5;f.elements.color.value=c?.color||DEFAULT_CARD_COLOR;
$('#card-form-title').textContent=c?'Editar cartão':'Adicionar cartão';$('#card-dialog').showModal();
}
function recurringPage(){
const rules=state.recurringRules||[],rows=recurringChargesForMonth(state,month);
const sum=list=>list.reduce((total,t)=>total+t.amount,0),paid=rows.filter(t=>t.status==='paid'),pending=rows.filter(t=>t.status==='pending');
return `<div class="recurring-controls"><button id="add-recurring" class="secondary">＋ Nova despesa recorrente</button><button id="pay-recurring-month" class="primary" ${pending.length?'':'disabled'}>Marcar todas do mês como pagas</button></div><div class="recurring-totals"><article class="panel panel-inner"><span>Total do mês</span><strong>${money(sum(rows))}</strong></article><article class="panel panel-inner"><span>Pagas · ${paid.length}</span><strong>${money(sum(paid))}</strong></article><article class="panel panel-inner"><span>Pendentes · ${pending.length}</span><strong>${money(sum(pending))}</strong></article></div><article class="panel panel-inner recurring-intro"><h2>Contas que fazem parte da rotina</h2><p class="notice">As recorrências ativas entram automaticamente nas despesas e gráficos ao abrir a carteira, salvar um cadastro ou trocar o mês. Meses anteriores ainda não registrados também são incluídos desde o início da recorrência. Assinale Pago para registrar a data do pagamento. Não é preciso gerar lançamentos manualmente.</p><div class="guide-actions"><button data-new-rule="health" class="secondary">＋ Plano de saúde</button><button data-new-rule="phone" class="secondary">＋ Plano de telefone</button><button data-new-rule="internet" class="secondary">＋ Internet</button></div></article><div class="recurring-grid">${rules.length?rules.map(r=>{
const charges=rows.filter(t=>t.recurringId===r.id);
const shifted=state.transactions.find(t=>t.recurringId===r.id&&t.recurringMonth===month&&credit(t)&&t.invoice!==month);
const processed=(state.recurringLedger||[]).some(e=>e.ruleId===r.id&&e.month===month)||(r.suppressedThroughMonth&&month<=r.suppressedThroughMonth);
return `<article class="panel panel-inner"><div class="panel-heading"><h2>${esc(r.description)}</h2><span class="pill ${r.active?'paid':'pending'}">${r.active?'Ativa':'Pausada'}</span></div><div class="invoice-value">${money(r.amount)}<small class="muted"> / mês</small></div><p class="recurring-details">Dia ${r.day} · ${esc(category(r.category)?.name)}<br>${esc(r.method)}${r.card?' · '+esc(card(r.card)?.name):''}<br>De ${esc(monthLabel(r.start))}${r.end?' até '+esc(monthLabel(r.end)):' · sem data final'}</p><div class="recurring-charges">${charges.length?charges.map(t=>`<div class="recurring-charge"><div><strong>${money(t.amount)}</strong><small>${credit(t)?'Fatura '+esc(t.invoice):'Vencimento '+fmtDate(t.date)}</small><small>${t.status==='paid'?'Pago em '+fmtDate(t.paidDate||t.date):'Pagamento pendente'}</small></div><label class="recurring-payment"><input type="checkbox" data-recurring-paid="${esc(t.id)}" ${t.status==='paid'?'checked':''} aria-label="Marcar ${esc(t.description)} como paga"><span>Pago</span></label><button data-edit="${esc(t.id)}" class="text-button">Editar cobrança</button></div>`).join(''):shifted?`<p class="notice">A cobrança com data neste mês está na fatura de ${esc(monthLabel(shifted.invoice))}, onde será contabilizada.</p>`:processed?'<p class="notice">Nenhuma cobrança nesta competência. Lançamentos apagados não são recriados automaticamente.</p>':!r.active?'<p class="notice">Pausada: não são criadas novas cobranças.</p>':'<p class="notice">Sem cobrança neste mês: confira o período da recorrência.</p>'}</div><div class="guide-actions"><button data-edit-rule="${esc(r.id)}" class="secondary">Editar recorrência</button><button data-toggle-rule="${esc(r.id)}" class="text-button">${r.active?'Pausar':'Ativar'}</button></div></article>`;
}).join(''):'<article class="panel empty">Nenhuma despesa recorrente cadastrada. Comece com um dos exemplos acima e informe o valor do seu plano.</article>'}</div><p class="notice">O total segue a mesma competência do painel: cartão usa o mês da fatura; os demais meios usam a data da cobrança. Marcar Pago reduz as pendências e atualiza o saldo na data efetiva, sem somar outra despesa. Desmarque para corrigir um pagamento. Editar ou pausar o cadastro não altera cobranças existentes. Ao reativar, a inclusão recomeça no mês selecionado; períodos pausados não são cobrados.</p>`;
}
function updateRecurringCard(){
const f=$('#recurring-form'),isCredit=f.elements.method.value==='Cartão de crédito';
$('#recurring-card-field').hidden=!isCredit;f.elements.card.required=isCredit;f.elements.card.disabled=!isCredit;
}
function openRecurring(id,preset){
const f=$('#recurring-form');f.reset();$('#recurring-error').textContent='';
f.elements.category.innerHTML=state.categories.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');
f.elements.method.innerHTML=methods.map(m=>`<option>${esc(m)}</option>`).join('');
f.elements.card.innerHTML=state.cards.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');
f.elements.id.value=id||crypto.randomUUID();f.elements.start.value=month;
const rule=(state.recurringRules||[]).find(r=>r.id===id);
if(rule){for(const [key,value] of Object.entries(rule))if(f.elements[key])f.elements[key].value=key==='amount'?value/100:String(value);}
else if(preset){const names={health:['Plano de saúde','Saúde'],phone:['Plano de telefone','Assinaturas'],internet:['Internet','Moradia']};const chosen=names[preset];if(chosen){f.elements.description.value=chosen[0];const c=state.categories.find(c=>c.name===chosen[1]);if(c)f.elements.category.value=c.id;}}
$('#recurring-title').textContent=rule?'Editar despesa recorrente':'Nova despesa recorrente';updateRecurringCard();$('#recurring-dialog').showModal();
}
$('#recurring-form').elements.method.addEventListener('change',updateRecurringCard);
$('#recurring-form').addEventListener('submit',e=>{e.preventDefault();try{
const d=Object.fromEntries(new FormData(e.target));
const rule={id:d.id,description:d.description,amount:Math.round(Number(d.amount)*100),day:Number(d.day),category:d.category,method:d.method,start:d.start,end:d.end||'',active:d.active==='true',...(d.card?{card:d.card}:{})};
if(commit(saveRecurringRule(state,rule,month))){$('#recurring-dialog').close();toast('Recorrência salva e despesas do mês atualizadas.');}
}catch(error){$('#recurring-error').textContent=error.message;}});

document.addEventListener('change',e=>{
const id=e.target.dataset.recurringPaid;if(!id)return;
const row=state.transactions.find(t=>t.id===id);if(!row)return;
const paid=e.target.checked;e.target.checked=row.status==='paid';
if(paid)showConfirm('Registrar pagamento?',row.description+' · '+money(row.amount)+'. Informe quando essa cobrança foi paga. O valor já está incluído nas despesas do mês.',date=>commit(setRecurringPayment(state,id,true,date)),true);
else showConfirm('Marcar cobrança como pendente?',row.description+' voltará para as pendências e o pagamento será retirado do saldo realizado.',()=>commit(setRecurringPayment(state,id,false)));
});
